import re

TIME_RE = re.compile(r"\b([01]?\d|2[0-3])(?::([0-5]\d))?\s*(am|pm)?\b", re.IGNORECASE)
START, LAST = 9 * 60, 17 * 60 + 30   # the last start whose 30-minute slot ends by 18:00


def out_of_hours(body):
    """Start times in the draft at which a 30-minute slot does not fit inside 09:00 to 18:00, each as "HH:MM", in order of appearance."""
    bad = []
    for h, m, ampm in TIME_RE.findall(body):
        if not m and not ampm:
            continue  # a bare number such as 70 or 3 is not a time
        h, m = int(h), int(m or 0)
        if ampm:
            if h > 12:
                continue
            h = h % 12 + (12 if ampm.lower() == "pm" else 0)
        t = h * 60 + m
        if t < START or t > LAST:
            bad.append(f"{h:02d}:{m:02d}")
    return bad
